shell_commands:
cat << 'EOF' > sum-usage-test.ts
    it('sums usage across multiple provider rounds', async () => {
      let receivedUsage: TurnUsage | undefined;
      const hooks: OrchestratorHooks = {
        afterModelResponse: async (_session, _text, u) => {
          receivedUsage = u;
        },
      };

      const registry = new ToolRegistry();
      registry.register({name: 'ping', description: 'ping', inputSchema: {type: 'object'}}, async () => 'pong');

      let round = 0;
      const provider: AIProvider = {
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          round++;
          if (round === 1) {
            yield {type: 'tool_use', toolCall: {id: 'c1', name: 'ping', input: {}}};
            yield {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}};
            return;
          }
          yield {type: 'text', text: 'pong received'};
          yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 3, totalTokens: 8}};
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
      await orchestrator.processMessage(createSession('hi'));

      expect(receivedUsage).toEqual({inputTokens: 15, outputTokens: 5, totalTokens: 20});
    });
EOF

